import json

with open('batches/batch_0047.json', encoding='utf-8') as f:
    data = json.load(f)

targets = {2351,2360,2375,2382,2385,2387,2390,2392}
out = {}
for item in data:
    if item['idx'] in targets:
        fixed = {}
        for field in ['title','desc','body']:
            s = item.get(field,'')
            if not s:
                fixed[field] = s
                continue
            try:
                b = s.encode('latin-1')
                d = b.decode('utf-8')
                fixed[field] = ('latin1->utf8', d)
                continue
            except Exception:
                pass
            try:
                b = s.encode('latin-1')
                d = b.decode('cp932')
                fixed[field] = ('latin1->cp932', d)
                continue
            except Exception:
                pass
            fixed[field] = ('RAW', s)
        out[item['idx']] = fixed

for idx, fields in out.items():
    print("=== idx", idx, "===")
    for k,(method,v) in fields.items():
        print(k, method, ":", v[:300].replace('\n','\\n'))
    print()
